import { useState, useRef } from 'react'
import type { ReactNode } from 'react'
import { Box, Collapsible, Image, Text } from '@chakra-ui/react'
import { BsArrowDownCircle } from 'react-icons/bs'

import { MyYesButton } from '~/ui/parts/MyButton'
import { VideoViewSimple } from '~/ui/parts/VideoView'
import type { VideoViewSimpleProp } from '~/ui/parts/VideoView'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'
import type { SerializedStyles } from '@emotion/react'


type PeriodProp = {
  lemma: ReactNode;
  children: ReactNode;
  css?: SerializedStyles;
}
export function Period(prop: PeriodProp) {
  const { lemma, children, css, ...otherProp } = prop;
  return (
    <Box shadow='md' css={[styles.period.container, css].flat()} {...otherProp}>
      <Lemma>{lemma}</Lemma>
      <Box className='detail' mt='0.5em' ml='5px'>
        {children}
      </Box>
    </Box>
  )
}

export function PreiodCollapsible(prop: PeriodProp) {
  const { lemma, children, css, ...otherProp } = prop;
  
  const [openCollap, setOpenCollap] = useState<boolean>(false);
  const collapTriggerRef = useRef<HTMLButtonElement | null>(null);
  const handlerClickDetail = () => setOpenCollap((curOpen) => {
    if (!curOpen) {
      collapTriggerRef.current?.focus({ preventScroll: true });
    }
    return true;
  });
  
  return (
    <Collapsible.Root asChild collapsedHeight='3em'
      open={openCollap} onOpenChange={(e) => setOpenCollap(e.open)}
      >
      <Box shadow='md' css={[styles.period.container, css].flat()} {...otherProp}>
        <Lemma>
          {lemma}
          <Collapsible.Trigger asChild>
            <MyYesButton size='sm'>
              <Collapsible.Context>
                {(api) => (api.open ? '折りたたむ' : 'すべて表示')}
              </Collapsible.Context>
              <Collapsible.Indicator
                transition='transform 0.2s'
                _open={{ transform: 'rotate(180deg)' }}
                >
                <BsArrowDownCircle />
              </Collapsible.Indicator>
            </MyYesButton>
          </Collapsible.Trigger>
        </Lemma>
        <Collapsible.Content
          asChild
          _closed={{
            shadow: 'inset 0 -12px 12px -12px var(--shadow-color)',
            shadowColor: 'blackAlpha.500',
          }}
          onClick={handlerClickDetail}
          >
          <Box className='detail' ml='5px'>
            {children}
          </Box>
        </Collapsible.Content>
      </Box>
    </Collapsible.Root>
  )
}


type LemmaProp = {
  children: ReactNode;
  css?: SerializedStyles;
}
export function Lemma(prop: LemmaProp) {
  const { children, ...otherProp } = prop;
  return (
    <Text className='lemma' fontWeight='bold' {...otherProp}>
      {children}
    </Text>
  )
}

type RemarksProp = {
  mark: string;
  fluid?: boolean;
  children: ReactNode;
}
export function Remarks(prop: RemarksProp) {
  const { mark, fluid, children } = prop;
  const fill = fluid ? "width: 100%;" : "";
  const style = css`
    font-size: 0.8em;
    display: inline-flex;
    ${fill}
    &:before {
      content: '${mark}';
      display: inline-block;
      padding-right: 0.3em;
    }
    > .details {
      display: inline-block;
      ${fill}
    }
  `
  return (
    <Text as='span' css={style}>
      <span className='details'>
        {children}
      </span>
    </Text>
  )
}

import { MyBasicCarousel } from '~/ui/parts/MyCarousel'

type WithCommentProp = {
  commentMinWidth?: string;
  comment?: ReactNode;
  css?: SerializedStyles | (SerializedStyles | undefined)[];
  children?: ReactNode;
}
type ImageWithCommentProp = WithCommentProp & {
  image: string;
  contentWidth?: string;
  contentAspectRatio?: string;
}
export function ImageWithComment(prop: ImageWithCommentProp) {
  const { image, contentWidth, contentAspectRatio, css, ...otherProp } = prop;
  const style = contentWidth ? undefined : styles.defaultContentWidth;
  
  return (
    <ContentWithComment
      css={[style, css].flat()}
      content={<Image className='content' src={image} w={contentWidth} aspectRatio={contentAspectRatio} objectFit='contain' loading='lazy' />}
      {...otherProp}
      />
  )
}

type ImagesWithCommentProp = WithCommentProp & {
  images: string[];
  contentWidth?: string;
  contentAspectRatio?: string;
}
export function ImagesWithComment(prop: ImagesWithCommentProp) {
  const { images, contentWidth, contentAspectRatio, css, ...otherProp } = prop;
  const style = contentWidth ? undefined : styles.defaultContentWidth;
  
  return (
    <ContentWithComment
      css={[style, css].flat()}
      content={<MyBasicCarousel
        w={contentWidth}
        slideList={images.map((image) => (
            <Image className='content' src={image} w={contentWidth} aspectRatio={contentAspectRatio} objectFit='contain' loading='lazy' />
          ))} />}
      {...otherProp}
      />
  )
}

type VideoWithCommentProp = WithCommentProp & VideoViewSimpleProp & {
  contentWidth?: string;
}
export function VideoWithComment(prop: VideoWithCommentProp) {
  const videoViewSimpleProp: VideoViewSimpleProp = prop;
  const withCommentProp: WithCommentProp = prop;
  // 動画は小さいと見づらいので、自動で縮めずにdefault 15emとする
  const { contentWidth = 'min(max(15em, 30%), 20em)' } = prop;
  
  return (
    <ContentWithComment
      //css={style}
      content={
        <Box className='content' w={contentWidth}>
          <VideoViewSimple {...videoViewSimpleProp} />
        </Box>}
      {...withCommentProp}
      />
  )
}


type ContentWithCommentProp = WithCommentProp & {
  content: ReactNode;
}
export function ContentWithComment(prop: ContentWithCommentProp) {
  const { content, commentMinWidth = 'min-content', comment, children, css, ...otherProp } = prop;
  
  // ※実はcss変数はundefinedだが、otherPropのおかげでcssとしてちゃんと適用される。
  //   でもcss変数を用意して、flatで1回のcss代入としないと、build時にcss設定重複の警告が出たので仕方なくこうしている。
  //   (ちなみに"css"以外の名前[例えば"csss"とか]にすると呼び元で設定した値が渡ってくるので、otherPropがなくてもOK)
  return (
    <Box as='figure' css={[styles.contentWithComment, css].flat()} {...otherProp}>
      {content}
      <Box as='figcaption' className='comment' flexGrow='1' flexBasis={commentMinWidth} ml='5px'>
        {comment ? comment : children}
      </Box>
    </Box>
  )
}


